@-moz-document domain("discord.com") {
/* 1. Target the text container boxes exclusively and force light mode compatibility */
  [class*="channelTextArea_"],
  [class*="inner_c6376c"],
  [class*="scrollableContainer_"] {
    background-image: linear-gradient(rgba(255, 255, 255, 0.45), rgba(255, 255, 255, 0.45)), url("https://media.discordapp.net/attachments/1453695293781446710/1532241228786172146/Untitled332_20250612115726_1.webp?ex=6a6c2258&is=6a6ad0d8&hm=3c5ffb091a502bbca19d54a3cd4a4c75e64a69c62725510f03727b5bb0fac1c7&=&format=webp") !important;
    background-size: cover !important;
    background-position: center !important;
    background-color: transparent !important;
    border: 1px solid rgba(0, 0, 0, 0.15) !important;
  }

  /* 2. Strip Discord's native light mode gray background color from the input fields */
  :root, .theme-light {
    --channeltextarea-background: transparent !important;
    --background-message-hover: rgba(0, 0, 0, 0.02) !important;
  }

  /* 3. Make sure the typing cursor area itself doesn't have a solid color */
  [class*="textArea_"],
  [class*="inner_"] {
    background: transparent !important;
    background-color: transparent !important;
  }
}
